return $input.all().map(item => {
  item.json.ytBody = {
    snippet: {
      title: item.json.title + ': ' + item.json.hook + ' #shorts',
      description: item.json.caption_youtube + '\n\n#shorts',
      tags: [
        "shorts","ytshorts","horrorstories","scary","horrorshorts",
        "creepystories","watchtilltheend","disturbing","paranormal","dontwatchalone"
      ],
      categoryId: 24
    },
    status: {
      privacyStatus: "private",
      selfDeclaredMadeForKids: false
    }
  };
  return item;
});

return $input.all().map(item => {
  if (typeof item.json.metadata !== "string") {
    throw new Error("Expected item.json.metadata to be a JSON string");
  }

  let parsed;
  try {
    parsed = JSON.parse(item.json.metadata);
  } catch (e) {
    throw new Error(
      `Failed to parse metadata JSON string: ${e.message}\n` +
      `Value: ${item.json.metadata.slice(0, 300)}`
    );
  }

  // Flatten fields so Set node can use them easily
  return {
    json: {
      title: parsed.title ?? "",
      hook: parsed.hook ?? "",
      caption_instagram: parsed.caption_instagram ?? "",
      caption_tiktok: parsed.caption_tiktok ?? "",
      caption_youtube: parsed.caption_youtube ?? "",
      fileBase: parsed.path ?? ""
    }
  };
});

return $input.all().map(item => {
  const b = item.binary?.Horrorvideo;

  if (!b) {
    throw new Error('FinalVideo binary missing');
  }

  // Force-correct the binary metadata
  item.binary = {
    Horrorvideo: {
      ...b,
      mimeType: 'video/mp4',
      fileType: 'video/mp4',
      fileExtension: 'mp4',
    }
  };

  return item;
});

// Exact byte count for TikTok's FILE_UPLOAD init (binary.fileSize is a rounded label).
const buf = await this.helpers.getBinaryDataBuffer(0, 'Horrorvideo');
return [{ json: { videoSize: buf.length } }];

// HTTP Request nodes drop input binaries, so re-attach the mp4 for the PUT.
const item = $input.first();
const src = $('Read Video File').first().binary?.Horrorvideo;
if (!src) throw new Error('Horrorvideo binary missing');
if (!item.json.data?.upload_url) throw new Error('TikTok init returned no upload_url: ' + JSON.stringify(item.json).slice(0, 500));
return [{ json: item.json, binary: { Horrorvideo: { ...src, mimeType: 'video/mp4', fileType: 'video/mp4', fileExtension: 'mp4' } } }];

// Which platforms are paused (blocked_<platform>.flag younger than 24 h). Metadata
// fields are carried through so downstream $json keeps working unchanged.
const parts = ($input.first().json.stdout || '').trim().toLowerCase().split(',');
const meta = $('Parse Metadata').first().json;
return [{ json: { ...meta,
  youtubeBlocked: parts[0] === 'true',
  instagramBlocked: parts[1] === 'true',
  tiktokBlocked: parts[2] === 'true' } }];
